/**
 * Ground nodes (ESP32 + LoRa). Positions, link stats and readings are
 * SIMULATED for the demo — generated by scripts/generate_demo_data.py.
 */
import type { DataProvenance, LinkQuality, SensorNode } from '@/types/domain'
import raw from './sensors.json'

const LINKS: ReadonlySet<string> = new Set(['good', 'fair', 'poor', 'offline'])

function toNode(n: unknown): SensorNode {
  const r = n as SensorNode
  const ok =
    typeof r?.id === 'string' &&
    typeof r.slopeId === 'string' &&
    Array.isArray(r.coordinates) &&
    r.coordinates.length === 2 &&
    LINKS.has(r.link) &&
    typeof r.rest?.soilDeep === 'number'
  if (!ok) throw new Error(`Invalid sensor node: ${JSON.stringify((n as { id?: string })?.id)}`)
  return { ...r, link: r.link as LinkQuality }
}

export const groundNodes: readonly SensorNode[] = (raw as { nodes: unknown[] }).nodes.map(toNode)

const byId = new Map(groundNodes.map((n) => [n.id, n]))
const bySlope = new Map(groundNodes.map((n) => [n.slopeId, n]))

export function getNode(id: string | null | undefined): SensorNode | undefined {
  return id ? byId.get(id) : undefined
}

export function getNodeForSlope(slopeId: string | null | undefined): SensorNode | undefined {
  return slopeId ? bySlope.get(slopeId) : undefined
}

export const NODE_PROVENANCE: DataProvenance = {
  kind: 'simulated',
  source: 'Deterministic demo telemetry',
  note: 'ESP32 · 2× capacitive soil moisture · MPU6050 tilt · tipping-bucket rain gauge · LoRa',
}
